Nginx Restic Backend
Written 6 years ago by Mike Cardwell
I’ve started using an excellent piece of software called
Restic
for backing up my various hosts. Restic has multiple backend types that you can send your backups to. One of the backends it supports is a
REST API
for which there is an implementation named
Rest Server
written in
Go
.
I thought to myself, if it’s just a simple REST API, why do I need to learn/install/manage a new piece of software? I already use
Nginx
all over the place. Can I just use Nginx for this? The answer was yes.
I have configured two nginx vhosts, and run them on different ports. One of the vhosts is to be accessed by hosts which are backing themselves up. It doesn’t allow them to delete objects (other than lock files), or overwrite them either. Meaning it is an “append-only” backup solution. The other vhost allows deletion, and exists for administrative tasks like pruning old backups.
For demo purposes, I’ve stripped a few things out of this config, e.g TLS. You will need to modify the config for your own use cases. Here is the the append-only config:
server {
listen
0.0
.
0.0
:
80
;
# In my testing, all objects are much smaller than 1GB in size, even if the file is larger. This may be tunable.
client_max_body_size
1000
M;
# We support Restic REST API v2, only
default_type
"application/vnd.x.restic.rest.v2"
;
# Authentication
auth_basic
"Restic Append-Only Backups"
;
auth_basic_user_file /opt/backups/auth/.htpasswd;
root                 /opt/backups/repo/
$remote_user
;
# Routing
error_page
470
= @list_objects;
error_page
471
= @read_object;
error_page
472
= @write_object;
error_page
473
= @delete_object;
error_page
474
= @put_proxy;
# Things that can be listed
location ~
"^/(data|keys|locks|snapshots|index)/
$
"
{
if
(
$request_method
=
'GET'
) {
return
470
; }
# @list_objects
return
403
;
}
# Reading the config file and keys
location ~
"^/(config|keys/[a-f0-9]{64})
$
"
{
if
(
$request_method
=
'HEAD'
) {
return
471
; }
# @read_object
if
(
$request_method
=
'GET'
)  {
return
471
; }
# @read_object
return
403
;
}
# Managing lock files
location ~
"^/locks/[a-f0-9]{64}
$
"
{
if
(
$request_method
=
'HEAD'
)   {
return
471
; }
# @read_object
if
(
$request_method
=
'GET'
)    {
return
471
; }
# @read_object
if
(
$request_method
=
'DELETE'
) {
return
473
; }
# @delete_object
if
(
$request_method
=
'PUT'
)    {
return
472
; }
# @write_object
if
(
$request_method
=
'POST'
)   {
return
474
; }
# @put_proxy
return
403
;
}
# Reading and Writing data, index and snapshots
location ~
"^/(data|index|snapshots)/[a-f0-9]{64}
$
"
{
if
(
$request_method
=
'HEAD'
) {
return
471
; }
# @read_object
if
(
$request_method
=
'GET'
)  {
return
471
; }
# @read_object
if
(
$request_method
=
'PUT'
)  {
return
472
; }
# @write_object
if
(
$request_method
=
'POST'
) {
return
474
; }
# @put_proxy
return
403
;
}
# Block everything else
location ~
"^"
{
return
403
;
}
# Reading objects
location @read_object {
}
# Writing objects
location @write_object {
# Prevent overwriting files
if
(
-f
$request_filename
) {
return
403
'No overwriting files'
;
}
dav_methods PUT;
create_full_put_path on;
dav_access user:rw;
}
# Deleting objects
location @delete_object {
dav_methods DELETE;
header_filter_by_lua_block {
if
ngx.status == ngx.HTTP_NO_CONTENT then
ngx.status = ngx.HTTP_OK
end
}
}
# Listing objects
location @list_objects {
autoindex            on;
autoindex_exact_size on;
autoindex_format     json;
body_filter_by_lua_block {
chunk = ngx.arg[
1
];
if
string.match(chunk,
'^<'
) then
chunk =
'[]'
ngx.arg[
2
] = true
else
chunk = ngx.arg[
1
];
chunk = ngx.re.gsub(chunk,
'\\s+'
,
''
)
chunk = ngx.re.gsub(chunk,
'"(?!name|size)[^"]+":"[^"]+"'
,
''
)
chunk = ngx.re.gsub(chunk,
',{2,}'
,
','
)
chunk = ngx.re.gsub(chunk,
'{,'
,
'{'
)
chunk = ngx.re.gsub(chunk,
',}'
,
'}'
)
end
ngx.arg[
1
] = chunk
}
header_filter_by_lua_block {
ngx.header[
"content-type"
] =
"application/vnd.x.restic.rest.v2"
;
if
ngx.status == ngx.HTTP_NOT_FOUND then
ngx.status = ngx.HTTP_OK
ngx.header[
"content-length"
] =
2
end
}
}
set_real_ip_from
127.0
.
0.1
;
location @put_proxy {
proxy_pass       http://
127.0
.
0.1
:
80
;
proxy_method     PUT;
proxy_set_header Host
$host
;
proxy_set_header X
-Real
-IP
$remote_addr
;
header_filter_by_lua_block {
if
ngx.status == ngx.HTTP_CREATED then
ngx.status = ngx.HTTP_OK
end
}
}
}
The config is laid out such that there are a handful of regex based location blocks at the top, which return error codes based on HTTP method, which are mapped to other location blocks below, which actually perform the requested action.
I used $remote_user in the “root” so that I could give each host it’s own set of credentials to use for basic auth, which would isolate each host into their own backup directory.
